    ok = ok && h.Band(0.05f) == 0 && h.Band(0.5f) == 2 && h.Band(0.8f) == 4;
    h.running = true;
    ok = ok && h.Band(0.8f) == 3;
    h.maxRun = 0.001f;
    ok = ok && h.Band(0.8f) == 0;
    std::printf(ok ? "006ab430_TEST PASS\n" : "006ab430_TEST FAIL\n");
